    this._viewGroup = new THREE.Group();
    this.camera.add(this._viewGroup);
    this.scene.add(this.camera);   // 确保 camera 加入场景，枪模跟随

    // 贴图：先用程序化贴图兜底，再异步加载联网下载的真实贴图替换（避免加载瞬间黑帧）
    const texMetal = this._makeMetalTexture();
    const texWood = this._makeWoodTexture();
    const texGrip = this._makeGripTexture();

    // USP 材质（黑金属，保持现状不动）：物理材质 + clearcoat，配合环境贴图产生真实反射
    const metalMat = new THREE.MeshPhysicalMaterial({ map: texMetal, color: 0x2a2d33, roughness: 0.35, metalness: 0.95, clearcoat: 0.3, clearcoatRoughness: 0.25 });
    const metalDarkMat = new THREE.MeshPhysicalMaterial({ map: texMetal, color: 0x15161a, roughness: 0.42, metalness: 0.9, clearcoat: 0.2, clearcoatRoughness: 0.3 });
    const woodMat = new THREE.MeshStandardMaterial({ map: texWood, roughness: 0.7, metalness: 0.02 });
    const gripMat = new THREE.MeshStandardMaterial({ map: texGrip, roughness: 0.8, metalness: 0.15 });

    // AK 卡通配色（采样自用户三视图：军绿 #565C46 / 暖木 #B98A4A）
    // 仍用 MeshPhysicalMaterial + clearcoat + IBL 环境反射——卡通配色 ≠ 2D 平面化，3D 质感保留
    // 第二次迭代（贴参考 3D 渲染图）：机匣金属改暖青铜军绿（#5a5e48 偏暖）更贴近
    const texArmy = this._makeArmyMetalTexture();
    const texArmyWarm = this._makeArmyMetalWarmTexture();
    const akArmyMat = new THREE.MeshPhysicalMaterial({ map: texArmy, roughness: 0.42, metalness: 0.78, clearcoat: 0.22, clearcoatRoughness: 0.32 });
    const akArmyWarmMat = new THREE.MeshPhysicalMaterial({ map: texArmyWarm, roughness: 0.40, metalness: 0.80, clearcoat: 0.25, clearcoatRoughness: 0.30 });
    const akArmyDarkMat = new THREE.MeshPhysicalMaterial({ map: texArmy, color: 0x8a8e82, roughness: 0.48, metalness: 0.72, clearcoat: 0.18, clearcoatRoughness: 0.38 });

    // USP 保持联网真实金属贴图覆盖（现状不动）；AK 卡通材质不做 CC0 覆盖，保持三视图配色
    this._applyTex(window.TEX && window.TEX.metal, [metalMat, metalDarkMat]);

    // 两把枪各自独立的高精度模型，切换时显隐
    this._viewGuns = {
      usp: this._buildUSP(metalMat, metalDarkMat, gripMat),
      ak47: this._buildAK(akArmyWarmMat, woodMat, akArmyMat, akArmyDarkMat),
    };
    this._viewGroup.add(this._viewGuns.usp);
    this._viewGroup.add(this._viewGuns.ak47);

    // 当前枪模姿态
    this._viewRecoil = 0;
  }

